package dev.konqasasas.beat.spigot;
import dev.konqasasas.beat.BeatPlugin;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.inventory.*;import org.bukkit.persistence.PersistentDataType;
final class TimeAttackItem {private final BeatPlugin p;private final NamespacedKey key;TimeAttackItem(BeatPlugin p){this.p=p;key=new NamespacedKey(p,"ta-restart-item");}boolean is(ItemStack i){return i!=null&&i.hasItemMeta()&&i.getItemMeta().getPersistentDataContainer().has(key,PersistentDataType.BYTE);}void give(Player x){for(var i:x.getInventory().getContents())if(is(i))return;String path="ta.restart-item";Material material=Material.matchMaterial(p.getConfig().getString(path+".material","RECOVERY_COMPASS"));if(material==null||material.isAir())material=Material.RECOVERY_COMPASS;var i=new ItemStack(material);var m=i.getItemMeta();m.setDisplayName(org.bukkit.ChatColor.translateAlternateColorCodes('&',p.getConfig().getString(path+".name","&eTA リスタート")));m.setLore(p.getConfig().getStringList(path+".lore").stream().map(s->org.bukkit.ChatColor.translateAlternateColorCodes('&',s)).toList());m.getPersistentDataContainer().set(key,PersistentDataType.BYTE,(byte)1);i.setItemMeta(m);x.getInventory().addItem(i);}void remove(Player x){for(int n=0;n<x.getInventory().getSize();n++)if(is(x.getInventory().getItem(n)))x.getInventory().setItem(n,null);}}
